// Сравнение календаря 2022 из CSV и JSON.
// Merge объединяет первый item CSV и первый item JSON по позиции.

const item = $input.first()?.json ?? {};

// После Merge:
// - CSV обычно находится в item.data (или item.body/response)
// - JSON содержит year, months и statistic непосредственно в item.

const csvText = String(
  item.data ??
  item.body ??
  item.response ??
  ''
);

function parseCsvLine(line) {
  const result = [];
  let value = '';
  let quoted = false;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];

    if (ch === '"') {
      if (quoted && line[i + 1] === '"') {
        value += '"';
        i++;
      } else {
        quoted = !quoted;
      }
    } else if (ch === ',' && !quoted) {
      result.push(value);
      value = '';
    } else {
      value += ch;
    }
  }

  result.push(value);
  return result;
}

const lines = csvText
  .replace(/^\uFEFF/, '')
  .split(/\r?\n/)
  .map(line => line.trim())
  .filter(Boolean);

if (lines.length < 2) {
  throw new Error(
    `CSV не содержит заголовок и строку данных. Получено строк: ${lines.length}`
  );
}

const headers = parseCsvLine(lines[0]);
const values = parseCsvLine(lines[1]);

const csv = {};
headers.forEach((header, index) => {
  csv[header] = values[index] ?? '';
});

const monthNames = [
  'Январь', 'Февраль', 'Март', 'Апрель', 'Май', 'Июнь',
  'Июль', 'Август', 'Сентябрь', 'Октябрь', 'Ноябрь', 'Декабрь'
];

const jsonYear = Number(item.year);
const csvYear = Number(csv['Год/Месяц']);

const differences = [];

if (!Number.isFinite(jsonYear)) {
  differences.push({
    field: 'year',
    csv: csvYear,
    json: item.year,
    reason: 'JSON year не найден или не является числом'
  });
} else if (csvYear !== jsonYear) {
  differences.push({
    field: 'year',
    csv: csvYear,
    json: jsonYear
  });
}

const jsonMonths = Array.isArray(item.months) ? item.months : [];

if (jsonMonths.length === 0) {
  differences.push({
    field: 'months',
    csv: '12 месяцев',
    json: item.months ?? null,
    reason: 'JSON months не найден'
  });
}

monthNames.forEach((monthName, index) => {
  const csvDays = String(csv[monthName] ?? '').trim();

  const jsonMonth = jsonMonths.find(
    m => Number(m?.month) === index + 1
  );

  const jsonDays = String(jsonMonth?.days ?? '').trim();

  if (csvDays !== jsonDays) {
    differences.push({
      field: `months.${index + 1}.days`,
      month: monthName,
      csv: csvDays,
      json: jsonDays
    });
  }
});

const statisticChecks = [
  ['Всего рабочих дней', 'workdays'],
  ['Всего праздничных и выходных дней', 'holidays'],
  ['Количество рабочих часов при 40-часовой рабочей неделе', 'hours40'],
  ['Количество рабочих часов при 36-часовой рабочей неделе', 'hours36'],
  ['Количество рабочих часов при 24-часовой рабочей неделе', 'hours24']
];

for (const [csvField, jsonField] of statisticChecks) {
  const csvValue = Number(
    String(csv[csvField] ?? '').replace(',', '.')
  );

  const jsonValue = Number(item.statistic?.[jsonField]);

  if (csvValue !== jsonValue) {
    differences.push({
      field: `statistic.${jsonField}`,
      csv: csvValue,
      json: jsonValue
    });
  }
}

const identical = differences.length === 0;

return [{
  json: {
    identical,
    message: identical
      ? 'CSV и JSON содержат идентичные общие данные календаря.'
      : 'CSV и JSON содержат различия.',
    compared: {
      year: true,
      months: 12,
      statistic: true
    },
    differences
  }
}];
